<script setup>
import {ref,reactive,computed,watch,onMounted} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {ElMessage,ElMessageBox} from 'element-plus';
import {useUserStore} from '../stores/user';
import {adminOverview,adminOrders,adminOrder,adminCancelOrder,adminItems,adminItemStatus,adminUsers,adminUserStatus,adminAudit,changePassword} from '../api';
import {formatPrice} from '../utils/format';
import OrderDetailDialog from '../components/OrderDetailDialog.vue';
const route=useRoute(),router=useRouter(),user=useUserStore();
const menus=[['overview','运营概览','DataAnalysis'],['orders','订单管理','Tickets'],['items','商品管理','Goods'],['users','用户管理','User'],['audit','操作日志','Document'],['account','账户设置','Setting']];
const tab=computed(()=>menus.some(m=>m[0]===route.query.tab)?route.query.tab:'overview');
const title=computed(()=>menus.find(m=>m[0]===tab.value)?.[1]);
const loading=ref(true),error=ref(''),overview=ref({}),rows=ref([]),total=ref(0),page=ref(1),keyword=ref(''),status=ref(''),detailOpen=ref(false),selectedOrder=ref(null),busy=ref(false),passwordBusy=ref(false);
const password=reactive({currentPassword:'',newPassword:'',confirm:''});let revision=0;
const statusOptions=computed(()=>tab.value==='orders'?[['pending','待交易'],['shipped','已发货'],['completed','已完成'],['cancelled','已取消']]:tab.value==='items'?[['on_sale','在售'],['off_shelf','已下架'],['reserved','已预定'],['sold','已售出']]:[['active','正常'],['disabled','已禁用']]);
const orderLabels={pending:'待交易',shipped:'已发货',completed:'已完成',cancelled:'已取消'};
const itemLabels={on_sale:'在售',off_shelf:'已下架',reserved:'已预定',sold:'已售出'};
const auditLabels={cancel_order:'取消订单',restore_item:'恢复商品在售',remove_item:'下架商品',enable_user:'启用账号',disable_user:'禁用账号',change_password:'修改密码'};
const when=value=>value?new Date(value).toLocaleString('zh-CN'):'—';
const metrics=computed(()=>[['用户总数',overview.value.users,'User'],['商品总数',overview.value.items,'Goods'],['在售商品',overview.value.onSale,'ShoppingBag'],['订单总数',overview.value.orders,'Tickets'],['待交易',overview.value.pending,'Clock'],['已发货',overview.value.shipped,'Van'],['已完成',overview.value.completed,'CircleCheck'],['已取消',overview.value.cancelled,'Close']]);
function go(value){router.replace({name:'admin',query:value==='overview'?{}:{tab:value}});}
async function load(){const own=++revision;loading.value=true;error.value='';try{if(tab.value==='account'){loading.value=false;return;}if(tab.value==='overview'){const data=await adminOverview();if(own===revision)overview.value=data;}else{const call={orders:adminOrders,items:adminItems,users:adminUsers,audit:adminAudit}[tab.value];const data=await call({page:page.value,pageSize:10,keyword:keyword.value.trim(),status:status.value});if(own===revision){const last=Math.max(1,Math.ceil(data.total/10));if(page.value>last){page.value=last;await load();return;}rows.value=data.list;total.value=data.total;}}}catch{if(own===revision)error.value='暂时无法加载管理数据，请重试。';}finally{if(own===revision)loading.value=false;}}
async function showOrder(row){try{selectedOrder.value=await adminOrder(row.id);detailOpen.value=true;}catch{}}
async function reasonFor(message){const answer=await ElMessageBox.prompt(message,'记录操作原因',{inputPlaceholder:'请填写原因，便于之后核对',inputValidator:value=>typeof value==='string'&&value.trim().length>=2&&value.trim().length<=200||'请填写2–200字操作原因',confirmButtonText:'确认操作',cancelButtonText:'取消'});return answer.value.trim();}
async function cancelOrder(row){if(busy.value)return;try{const reason=await reasonFor(`取消订单 ${row.orderNo} 后，商品将恢复在售。`);busy.value=true;await adminCancelOrder(row.id,{reason});ElMessage.success('订单已取消，已记录操作日志');await load();}catch{}finally{busy.value=false;}}
async function toggleItem(row){if(busy.value)return;const next=row.status==='on_sale'?'off_shelf':'on_sale';try{const reason=await reasonFor(`确认将「${row.title}」${next==='off_shelf'?'下架':'恢复在售'}？`);busy.value=true;await adminItemStatus(row.id,{status:next,reason});ElMessage.success('商品状态已更新');await load();}catch{}finally{busy.value=false;}}
async function toggleUser(row){if(busy.value)return;const next=row.status==='active'?'disabled':'active';try{const reason=await reasonFor(`${next==='disabled'?'禁用':'启用'}账号 ${row.username}，${next==='disabled'?'将停止该账号的登录和接口访问。':'恢复该账号的使用。'}`);busy.value=true;await adminUserStatus(row.id,{status:next,reason});ElMessage.success('账号状态已更新');await load();}catch{}finally{busy.value=false;}}
async function logout(){try{await ElMessageBox.confirm('退出当前管理账号？','退出登录');user.logout();router.replace({name:'login'});}catch{}}
async function savePassword(){if(passwordBusy.value)return;if(!password.currentPassword||password.newPassword.length<6||password.newPassword.length>20){ElMessage.warning('请填写当前密码，以及6–20位新密码');return;}if(password.newPassword!==password.confirm){ElMessage.warning('两次新密码不一致');return;}passwordBusy.value=true;try{await changePassword({currentPassword:password.currentPassword,newPassword:password.newPassword});user.logout();ElMessage.success('密码已更新，请重新登录');router.replace({name:'login'});}catch{}finally{passwordBusy.value=false;}}
watch(tab,()=>{page.value=1;keyword.value='';status.value='';rows.value=[];load();});onMounted(load);
</script>
<template><div class="admin-app"><aside class="admin-side"><RouterLink :to="{name:'admin'}" class="admin-brand"><span>拾</span><div><b>拾光集市</b><small>管理控制台</small></div></RouterLink><span class="admin-nav-caption">工作空间</span><nav aria-label="后台导航"><button v-for="[value,label,icon] in menus" :key="value" :class="{active:tab===value}" @click="go(value)"><el-icon><component :is="icon"/></el-icon><span>{{label}}</span></button></nav><div class="admin-side-bottom"><RouterLink :to="{name:'home'}"><el-icon><House/></el-icon>查看网站</RouterLink><span>Campus marketplace</span></div></aside><div class="admin-workspace"><header class="admin-topbar"><div><span>管理后台</span><b>{{title}}</b></div><div class="admin-account"><span class="small-avatar">{{user.user?.nickname?.[0]||'管'}}</span><span>{{user.user?.username}}</span><RouterLink class="admin-mobile-site-link" :to="{name:'home'}">查看网站</RouterLink><el-button text @click="logout">退出登录</el-button></div></header><main class="admin-main"><div class="admin-page-heading"><div><span class="eyebrow">SHIGUANG WORKSPACE</span><h1>{{title}}</h1><p>{{tab==='overview'?'每一件好物，每一次交接，都有迹可循。':tab==='orders'?'核对订单、交付进度和交易记录。':tab==='items'?'管理真实在售商品，维护集市秩序。':tab==='users'?'管理账号状态，保护正常交易。':tab==='audit'?'管理操作留痕，便于核查与追溯。':'管理你的登录密码。'}}</p></div><el-button v-if="tab!=='account'" :loading="loading" @click="load">刷新数据</el-button></div>
 <div v-if="error" class="inline-error">{{error}}<el-button @click="load">重新加载</el-button></div>
 <template v-else-if="tab==='overview'"><div v-loading="loading" class="admin-metrics"><article v-for="[label,value,icon] in metrics" :key="label" class="admin-metric"><span>{{label}}</span><b>{{value??0}}</b><el-icon><component :is="icon"/></el-icon></article></div><section class="admin-panel"><div class="admin-panel-heading"><h2>最近订单</h2><el-button text @click="go('orders')">查看全部订单</el-button></div><el-table :data="overview.recentOrders||[]" empty-text="暂无订单"><el-table-column prop="orderNo" label="订单号" min-width="170"/><el-table-column prop="itemTitle" label="商品" min-width="210"/><el-table-column label="金额" min-width="90"><template #default="{row}">{{formatPrice(row.price)}}</template></el-table-column><el-table-column label="状态" min-width="90"><template #default="{row}"><el-tag size="small">{{orderLabels[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button text @click="showOrder(row)">详情</el-button></template></el-table-column></el-table></section><div class="admin-operating-note"><el-icon><CircleCheck/></el-icon><p>订单、商品、用户状态与管理操作记录会实时保存。需要发布商品时，可前往网站使用发布入口。</p></div></template>
 <section v-else-if="tab==='account'" class="admin-panel admin-password"><h2>修改登录密码</h2><p class="text-sub">修改后当前账号的旧登录凭证会失效。</p><el-form label-position="top" @submit.prevent="savePassword"><el-form-item label="当前密码"><el-input v-model="password.currentPassword" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="新密码"><el-input v-model="password.newPassword" type="password" maxlength="20" show-password autocomplete="new-password" placeholder="6–20位"/></el-form-item><el-form-item label="再次输入新密码"><el-input v-model="password.confirm" type="password" maxlength="20" show-password autocomplete="new-password"/></el-form-item><el-button type="primary" native-type="submit" :loading="passwordBusy">保存新密码</el-button></el-form></section>
 <section v-else class="admin-panel"><form v-if="tab!=='audit'" class="admin-filter" @submit.prevent="page=1;load()"><el-input v-model="keyword" :placeholder="tab==='orders'?'搜索订单号或商品名称':tab==='items'?'搜索商品名称':'搜索账号或昵称'" aria-label="后台搜索" clearable/><el-select v-model="status" placeholder="全部状态" aria-label="后台状态筛选" clearable @change="page=1;load()"><el-option v-for="[value,label] in statusOptions" :key="value" :label="label" :value="value"/></el-select><el-button type="primary" native-type="submit">搜索</el-button></form>
  <div v-loading="loading" class="admin-table-wrap"><el-table v-if="tab==='orders'" :data="rows" empty-text="暂无符合条件的订单"><el-table-column prop="orderNo" label="订单号" min-width="170"/><el-table-column prop="itemTitle" label="商品" min-width="200"/><el-table-column label="交易双方" min-width="150"><template #default="{row}"><span>买家：{{row.buyerNickname}}</span><br/><span class="text-sub">卖家：{{row.sellerNickname}}</span></template></el-table-column><el-table-column label="金额" min-width="90"><template #default="{row}">{{formatPrice(row.price)}}</template></el-table-column><el-table-column label="状态" min-width="95"><template #default="{row}"><el-tag size="small" :type="row.status==='completed'?'success':row.status==='cancelled'?'info':'warning'">{{orderLabels[row.status]}}</el-tag></template></el-table-column><el-table-column label="下单时间" min-width="175"><template #default="{row}">{{when(row.createdAt)}}</template></el-table-column><el-table-column label="操作" min-width="160" fixed="right"><template #default="{row}"><el-button text @click="showOrder(row)">详情</el-button><el-button v-if="row.status==='pending'" text type="danger" :disabled="busy" @click="cancelOrder(row)">取消订单</el-button></template></el-table-column></el-table>
  <el-table v-else-if="tab==='items'" :data="rows" empty-text="暂无符合条件的商品"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="title" label="商品名称" min-width="230"/><el-table-column prop="sellerNickname" label="卖家" min-width="100"/><el-table-column prop="categoryName" label="分类" min-width="100"/><el-table-column label="价格" min-width="90"><template #default="{row}">{{formatPrice(row.price)}}</template></el-table-column><el-table-column label="状态" min-width="100"><template #default="{row}"><el-tag size="small" :type="row.status==='on_sale'?'success':'info'">{{itemLabels[row.status]}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="150" fixed="right"><template #default="{row}"><RouterLink class="text-link" :to="{name:'itemDetail',params:{id:row.id}}">查看</RouterLink><el-button v-if="['on_sale','off_shelf'].includes(row.status)" text :disabled="busy" @click="toggleItem(row)">{{row.status==='on_sale'?'下架':'恢复在售'}}</el-button></template></el-table-column></el-table>
  <el-table v-else-if="tab==='users'" :data="rows" empty-text="暂无符合条件的用户"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="username" label="账号" min-width="145"/><el-table-column prop="nickname" label="昵称" min-width="130"/><el-table-column label="角色" min-width="100"><template #default="{row}">{{row.role==='admin'?'管理员':'普通用户'}}</template></el-table-column><el-table-column label="状态" min-width="100"><template #default="{row}"><el-tag size="small" :type="row.status==='active'?'success':'danger'">{{row.status==='active'?'正常':'已禁用'}}</el-tag></template></el-table-column><el-table-column label="注册时间" min-width="175"><template #default="{row}">{{when(row.createdAt)}}</template></el-table-column><el-table-column label="操作" min-width="120" fixed="right"><template #default="{row}"><span v-if="row.id===user.user?.id" class="text-sub">当前账号</span><el-button v-else text :type="row.status==='active'?'danger':'primary'" :disabled="busy" @click="toggleUser(row)">{{row.status==='active'?'禁用账号':'启用账号'}}</el-button></template></el-table-column></el-table>
  <el-table v-else :data="rows" empty-text="暂无管理操作记录"><el-table-column prop="actorName" label="操作人" min-width="130"/><el-table-column label="操作" min-width="150"><template #default="{row}">{{auditLabels[row.action]||row.action}}</template></el-table-column><el-table-column label="对象" min-width="130"><template #default="{row}">{{row.targetType}} #{{row.targetId}}</template></el-table-column><el-table-column prop="detail" label="说明 / 原因" min-width="250"/><el-table-column label="时间" min-width="175"><template #default="{row}">{{when(row.createdAt)}}</template></el-table-column></el-table></div><div class="admin-pagination"><span>共 {{total}} 条记录</span><el-pagination v-if="total>10" v-model:current-page="page" :page-size="10" :total="total" layout="prev,pager,next" @current-change="load"/></div></section>
 </main></div><OrderDetailDialog v-model="detailOpen" :order="selectedOrder"/></div></template>
